INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"e7cab508-1f96-50cc-a4f9-33bb6d759616","title":"Business Studies · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A business installs an accessible entrance and adapts tasks for a qualified worker with a disability. Which principle is supported?","options":["Automatic exclusion","Inclusivity and reasonable accommodation","Price discrimination by definition","Avoidance of all quality standards"],"correct_index":1,"explanation":"Removing unnecessary barriers helps people participate fairly. Accommodation should respond to the worker's needs and job context.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why state the source and date of a chart in a presentation?","options":["So the audience can judge relevance and verify the evidence","To make every old figure current","To avoid explaining the chart","To guarantee the chart is unbiased"],"correct_index":0,"explanation":"Source and date help the audience assess credibility and currency. The presenter must still explain methods, units and limitations.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A SWOT analysis identifies a firm's strong customer service. Which category is it?","options":["Threat","Opportunity","External weakness","Strength"],"correct_index":3,"explanation":"A strength is an internal advantage. Opportunities and threats arise mainly outside the business.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can limited liability matter when choosing a company form?","options":["Shareholders' exposure is generally limited, subject to legal exceptions","It guarantees company debts never exist","It prevents every director from any liability","It means no records are needed"],"correct_index":0,"explanation":"Limited liability generally separates company obligations from shareholders, but legal exceptions and directors' duties still matter.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A SWOT lists a new competitor as a weakness and poor staff training as a threat. Which correction is justified?","options":["Both belong under strengths because they can be improved.","Both are opportunities because every change is beneficial.","The competitor is an external threat; inadequate training is an internal weakness.","Training is always external and competition always internal."],"correct_index":2,"explanation":"SWOT distinguishes internal capabilities from external conditions. A competing firm is external, while the business's own staff-development gap is internal; the distinction guides suitable responses.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Mixed revision: Human rights, responsibility and presentations; Integrated business decision revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"a97c0b2b-d98d-5b9c-9f35-86e9dbda5c2b","title":"Business Studies · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A manager consults team members before deciding. Which leadership style best fits?","options":["Democratic","Autocratic","Laissez-faire with no input","Coercive by definition"],"correct_index":0,"explanation":"Democratic leadership involves participation and consultation. It does not mean every decision must be unanimous.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which statement describes insurance pooling?","options":["Every premium is returned in full every month","Every loss is covered without exclusions","Insurers remove every possible business risk","Many policyholders' premiums help fund covered claims subject to policy terms"],"correct_index":3,"explanation":"Pooling spreads specified risks. Coverage, exclusions, excesses and other terms determine what a claim can pay.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A SWOT analysis identifies a firm's strong customer service. Which category is it?","options":["Threat","Opportunity","External weakness","Strength"],"correct_index":3,"explanation":"A strength is an internal advantage. Opportunities and threats arise mainly outside the business.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can limited liability matter when choosing a company form?","options":["Shareholders' exposure is generally limited, subject to legal exceptions","It guarantees company debts never exist","It prevents every director from any liability","It means no records are needed"],"correct_index":0,"explanation":"Limited liability generally separates company obligations from shareholders, but legal exceptions and directors' duties still matter.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A SWOT lists a new competitor as a weakness and poor staff training as a threat. Which correction is justified?","options":["Both belong under strengths because they can be improved.","Both are opportunities because every change is beneficial.","The competitor is an external threat; inadequate training is an internal weakness.","Training is always external and competition always internal."],"correct_index":2,"explanation":"SWOT distinguishes internal capabilities from external conditions. A competing firm is external, while the business's own staff-development gap is internal; the distinction guides suitable responses.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Mixed revision: Leadership, quality and investments; Integrated business decision revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"326dc475-dfa7-5eb3-9a9d-74705c5ee16c","title":"Business Studies · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 12","questions":[{"question":"A manager consults team members before deciding. Which leadership style best fits?","options":["Democratic","Autocratic","Laissez-faire with no input","Coercive by definition"],"correct_index":0,"explanation":"Democratic leadership involves participation and consultation. It does not mean every decision must be unanimous.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which statement describes insurance pooling?","options":["Every premium is returned in full every month","Every loss is covered without exclusions","Insurers remove every possible business risk","Many policyholders' premiums help fund covered claims subject to policy terms"],"correct_index":3,"explanation":"Pooling spreads specified risks. Coverage, exclusions, excesses and other terms determine what a claim can pay.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What does the triple bottom line consider?","options":["Only quarterly profit","Only the number of advertisements","People, planet and profit","Only staff uniforms"],"correct_index":2,"explanation":"A broader assessment considers social, environmental and economic performance. Financial results alone do not show all effects of business activity.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which example most clearly represents a CSI project?","options":["Recording daily sales","Pricing stock for a normal sale","Calculating a routine payslip","Funding and equipping a community learning centre"],"correct_index":3,"explanation":"Corporate social investment involves resources committed to community-development initiatives. Evaluate outcomes and sustainability, not just spending.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A firm funds a community centre but ignores complaints about unsafe waste disposal. Which assessment fits the triple bottom line?","options":["Any donation proves full sustainability.","Only the size of the donation matters.","The CSI project does not remove the need to address environmental and social harms.","Community benefits automatically cancel every environmental cost."],"correct_index":2,"explanation":"People, planet and profit must all be considered. Assess the centre's benefit alongside the firm's operating impacts and require evidence of corrective environmental action.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Mixed revision: Leadership, quality and investments; Human rights, responsibility and presentations","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PIlgg85LNBo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"17c579b0-9594-5e8f-9246-32c6815dc529","title":"Economics · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 12","questions":[{"question":"A price index rises from 120 to 126. Find the inflation rate for the period.","options":["6%","4.76%","5%","126%"],"correct_index":2,"explanation":"Inflation = (126−120)/120×100=5%. The six index points are not six percent of the original index.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which indicator combines health, education and income dimensions?","options":["Consumer Price Index only","Human Development Index","Exchange rate only","Prime lending rate"],"correct_index":1,"explanation":"HDI combines life expectancy, education and income measures. It complements economic output indicators rather than measuring every aspect of well-being.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why does real GDP per capita provide more context than total real GDP alone?","options":["It relates real output to population size","It measures every household's exact income","It removes all inequality automatically","It excludes population from analysis"],"correct_index":0,"explanation":"Divide real GDP by population. An average helps comparison but does not show how income is distributed.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"If the rand depreciates against the dollar, what happens to the rand price of a fixed dollar import price, all else equal?","options":["It falls","It rises","It necessarily stays equal","It becomes zero"],"correct_index":1,"explanation":"A weaker rand means more rand are needed for each dollar. Actual prices may also depend on contracts, taxes and other costs.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"In a simplified multiplier model MPC=0.8 gives k=5. Why should a R1 million injection not be treated as a guaranteed R5 million real-output increase in practice?","options":["The model proves unlimited resources exist.","A multiplier of five means every household receives R5 million.","Leakages, capacity limits, imports and behavioural responses can change the outcome.","Government spending can never affect demand."],"correct_index":2,"explanation":"The simple model rests on restrictive assumptions. Real economies have taxes, imports, saving changes and capacity constraints, so its predicted total effect needs contextual qualification.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Mixed revision: Inflation, indicators and sustainable tourism; Integrated macro- and microeconomics revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"dee73d75-692d-5111-85b3-f66395277484","title":"Economics · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 12","questions":[{"question":"In perfect competition, an individual firm is generally a…","options":["Sole market supplier","Price taker","Legal monopoly by definition","Setter of the market price independently"],"correct_index":1,"explanation":"A small firm sells an identical product in a market with many buyers and sellers, so it takes the market price in the model.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What is a tariff?","options":["A tax on imported goods","A quota on how many workers can apply","A ban on all domestic production","A guaranteed subsidy to every consumer"],"correct_index":0,"explanation":"Import tariffs raise the cost of imported goods and can protect domestic producers, but may raise consumer costs and invite retaliation.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why does real GDP per capita provide more context than total real GDP alone?","options":["It relates real output to population size","It measures every household's exact income","It removes all inequality automatically","It excludes population from analysis"],"correct_index":0,"explanation":"Divide real GDP by population. An average helps comparison but does not show how income is distributed.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"If the rand depreciates against the dollar, what happens to the rand price of a fixed dollar import price, all else equal?","options":["It falls","It rises","It necessarily stays equal","It becomes zero"],"correct_index":1,"explanation":"A weaker rand means more rand are needed for each dollar. Actual prices may also depend on contracts, taxes and other costs.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"In a simplified multiplier model MPC=0.8 gives k=5. Why should a R1 million injection not be treated as a guaranteed R5 million real-output increase in practice?","options":["The model proves unlimited resources exist.","A multiplier of five means every household receives R5 million.","Leakages, capacity limits, imports and behavioural responses can change the outcome.","Government spending can never affect demand."],"correct_index":2,"explanation":"The simple model rests on restrictive assumptions. Real economies have taxes, imports, saving changes and capacity constraints, so its predicted total effect needs contextual qualification.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Mixed revision: Market structures, failure and trade; Integrated macro- and microeconomics revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"6f6d1d83-dfd9-5afe-87e9-99435136cb80","title":"Economics · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 12","questions":[{"question":"In perfect competition, an individual firm is generally a…","options":["Sole market supplier","Price taker","Legal monopoly by definition","Setter of the market price independently"],"correct_index":1,"explanation":"A small firm sells an identical product in a market with many buyers and sellers, so it takes the market price in the model.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What is a tariff?","options":["A tax on imported goods","A quota on how many workers can apply","A ban on all domestic production","A guaranteed subsidy to every consumer"],"correct_index":0,"explanation":"Import tariffs raise the cost of imported goods and can protect domestic producers, but may raise consumer costs and invite retaliation.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What can cause demand-pull inflation?","options":["A fall in every source of demand","A guaranteed fall in the money supply alone","All productive resources become free","Aggregate demand grows faster than available real output at capacity"],"correct_index":3,"explanation":"Pressure from total spending can bid up prices when real output cannot expand sufficiently. Distinguish this from cost-push pressures.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why is tourism described as having a multiplier effect?","options":["Tourist spending generates further income and spending in connected activities","Every rand automatically doubles exactly once","All spending stays inside one hotel","Imports do not affect any tourism income"],"correct_index":0,"explanation":"Initial spending supports incomes, some of which are spent again. Saving, taxes and imports are leakages that affect the size of the effect.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"The inflation rate falls from 8% to 5%, remaining positive. A learner says average prices have fallen. Which correction is right?","options":["Prices must fall by 3% because the rate fell by three points.","All goods now have unchanged prices.","Prices are rising more slowly; a lower positive inflation rate is not a fall in the price level.","Inflation measures only employment."],"correct_index":2,"explanation":"Inflation is the rate of increase of the general price level. A fall in that positive rate is disinflation, while a falling general price level would require negative inflation.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Mixed revision: Market structures, failure and trade; Inflation, indicators and sustainable tourism","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dq9Dq46iLKo%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"bff27641-9edd-58d9-a52b-e85eace146f5","title":"Geography · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 12","questions":[{"question":"Which activity belongs to the primary sector?","options":["Manufacturing steel","Banking","Retailing clothes","Mining iron ore"],"correct_index":3,"explanation":"The primary sector extracts or produces raw materials. Steelmaking transforms them in the secondary sector.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why do mining benefits need to be assessed alongside costs?","options":["Mining creates no costs","All communities receive identical benefits","Jobs and export earnings can coexist with environmental and social impacts","Only export value matters"],"correct_index":2,"explanation":"Evaluate employment, revenue, land, water, health, rehabilitation and distribution. A balanced assessment uses evidence from affected areas.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"What does a drainage basin include?","options":["Only the river mouth","The area drained by a river and its tributaries","Only the deepest channel point","Every ocean connected to any river"],"correct_index":1,"explanation":"Watershed boundaries separate drainage basins. Water within a basin generally drains towards its river system.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What often happens where warm, moist air rises up a mountain slope?","options":["It always heats without limit","Water vapour instantly becomes rock","It cools, may condense and can produce orographic rain","Every cloud evaporates regardless of conditions"],"correct_index":2,"explanation":"Rising air expands and cools. If it reaches saturation, condensation can form cloud and precipitation on the windward slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Two points are 2 km apart in a straight line on a map. A learner says the walking route must take 20 minutes at 6 km/h. Why is this uncertain?","options":["Map scale guarantees every route is flat.","Walking speed cannot be related to distance.","The path may be longer or steeper than the straight-line distance.","Straight-line distance always includes detours."],"correct_index":2,"explanation":"The 20-minute calculation assumes a 2 km route at constant 6 km/h. Actual paths, contours, obstacles and stops may change distance and speed; use route and relief information.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Mixed revision: South Africa's economic geography; Climate, drainage and map-skill revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"04304a95-d0c8-55b8-beab-7d37e5b43a8a","title":"Geography · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 12","questions":[{"question":"What is river rejuvenation?","options":["A river ceasing every process permanently","The automatic creation of a lake at every mouth","Renewed erosive energy, often following a fall in base level or land uplift","A river becoming older by one year"],"correct_index":2,"explanation":"A change in relative base level or gradient can renew vertical erosion. Features can include incised meanders or knickpoints.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why may informal settlements develop rapidly near cities?","options":["Every resident prefers poor services","Affordable formal housing may not keep pace with migration and household formation","Urban housing demand is always zero","They occur only where no jobs exist"],"correct_index":1,"explanation":"Housing supply, land access, incomes and population change interact. Avoid explanations that blame residents or assume one universal cause.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"What does a drainage basin include?","options":["Only the river mouth","The area drained by a river and its tributaries","Only the deepest channel point","Every ocean connected to any river"],"correct_index":1,"explanation":"Watershed boundaries separate drainage basins. Water within a basin generally drains towards its river system.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What often happens where warm, moist air rises up a mountain slope?","options":["It always heats without limit","Water vapour instantly becomes rock","It cools, may condense and can produce orographic rain","Every cloud evaporates regardless of conditions"],"correct_index":2,"explanation":"Rising air expands and cools. If it reaches saturation, condensation can form cloud and precipitation on the windward slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Two points are 2 km apart in a straight line on a map. A learner says the walking route must take 20 minutes at 6 km/h. Why is this uncertain?","options":["Map scale guarantees every route is flat.","Walking speed cannot be related to distance.","The path may be longer or steeper than the straight-line distance.","Straight-line distance always includes detours."],"correct_index":2,"explanation":"The 20-minute calculation assumes a 2 km route at constant 6 km/h. Actual paths, contours, obstacles and stops may change distance and speed; use route and relief information.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"Mixed revision: Fluvial processes and settlements; Climate, drainage and map-skill revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"a260a584-aa0f-5e68-9cd0-0b4b3dd3872b","title":"Geography · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 12","questions":[{"question":"What is river rejuvenation?","options":["A river ceasing every process permanently","The automatic creation of a lake at every mouth","Renewed erosive energy, often following a fall in base level or land uplift","A river becoming older by one year"],"correct_index":2,"explanation":"A change in relative base level or gradient can renew vertical erosion. Features can include incised meanders or knickpoints.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why may informal settlements develop rapidly near cities?","options":["Every resident prefers poor services","Affordable formal housing may not keep pace with migration and household formation","Urban housing demand is always zero","They occur only where no jobs exist"],"correct_index":1,"explanation":"Housing supply, land access, incomes and population change interact. Avoid explanations that blame residents or assume one universal cause.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Why can transport infrastructure influence industrial location?","options":["It affects access to inputs, markets and distribution costs","Factories never need inputs","All transport costs are identical everywhere","It removes the need for labour"],"correct_index":0,"explanation":"Transport is one location factor alongside labour, power, water, land and policy. Different industries weigh these differently.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Which best describes small-scale subsistence farming?","options":["Only production for global export chains","Production mainly for the household's own use","Mining on agricultural land","A guarantee of no surplus in any year"],"correct_index":1,"explanation":"Subsistence farming primarily meets household needs; some surplus may be sold. Scale and production purpose are related but distinct.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"A proposed mine promises jobs but threatens a river used by downstream farms. Which evidence is needed for a balanced decision?","options":["Only the promoter's projected job number.","Only a promotional photograph of machinery.","Credible employment estimates and environmental, water-use and community-impact assessments.","An assumption that economic benefits erase all environmental costs."],"correct_index":2,"explanation":"Economic geography weighs benefits and costs across places and groups. Investigate water impacts, mitigation and who gains or bears risks alongside employment and revenue.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Mixed revision: Fluvial processes and settlements; South Africa's economic geography","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=PbIoAvtDReA%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"4b95259b-1a34-509d-a105-f23b765a32f6","title":"History · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"History","grade":"Grade 12","questions":[{"question":"What does globalisation describe?","options":["Increasing cross-border connections in economies, politics, culture and communication","The end of all international interaction","Only migration between two villages","A single country's weather pattern"],"correct_index":0,"explanation":"Globalisation has several dimensions and uneven effects. Define the dimension relevant to the question before evaluating its consequences.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"What makes an argument about a new world order convincing?","options":["Only a slogan","A list of dates with no relationship to the question","Ignoring evidence from outside one country","A supported claim that weighs change, continuity and competing interpretations"],"correct_index":3,"explanation":"A strong argument links evidence across cases to a clear judgment, while acknowledging limits and alternative interpretations.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is the best way to introduce a historical essay?","options":["Repeat every fact you remember","Avoid taking any position","State a clear position responding to the question and outline its line of argument","Copy the question without adding meaning"],"correct_index":2,"explanation":"The introduction should frame the argument. The body supports it with evidence and the conclusion returns to the judgment.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"How should a learner use a political cartoon as evidence?","options":["Treat every drawing as a literal photograph","Assume humour means it has no historical use","Ignore captions and dates","Interpret symbols and message in relation to creator, audience and historical context"],"correct_index":3,"explanation":"Cartoons compress and exaggerate viewpoints. Context and visual details help explain the message and its limitations as evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An essay uses an event in 1965 as the cause of a policy adopted in 1960. What revision is needed?","options":["Keep the claim because all related events are interchangeable.","Remove every date from the essay.","Correct the chronology and identify earlier causes; the later event may be a consequence or later development.","Treat the later event as earlier without evidence."],"correct_index":2,"explanation":"A cause must precede its effect. Establish an accurate sequence and distinguish origins, consequences and later reinforcement before building a causal argument.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"Mixed revision: Globalisation and a new world order; Source-based and essay examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7b7cbd06-fe55-5f92-9275-c44c266c3665","title":"History · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"History","grade":"Grade 12","questions":[{"question":"What was a central emphasis of Black Consciousness associated with Steve Biko?","options":["Acceptance of apartheid's racial hierarchy","Withdrawal of all criticism of oppression","A claim that only legislation affects identity","Psychological liberation, dignity and self-reliance among oppressed black people"],"correct_index":3,"explanation":"Black Consciousness challenged internalised oppression and promoted agency and solidarity. Explain its context and influence using specific evidence.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why evaluate both achievements and limitations of reconciliation initiatives?","options":["Stated aims automatically prove success","Critical evaluation is incompatible with evidence","Their aims and actual effects may differ across people and issues","All testimony gives the same experience"],"correct_index":2,"explanation":"A balanced argument compares goals, processes and outcomes, including justice, acknowledgement and unresolved material inequalities.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is the best way to introduce a historical essay?","options":["Repeat every fact you remember","Avoid taking any position","State a clear position responding to the question and outline its line of argument","Copy the question without adding meaning"],"correct_index":2,"explanation":"The introduction should frame the argument. The body supports it with evidence and the conclusion returns to the judgment.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"How should a learner use a political cartoon as evidence?","options":["Treat every drawing as a literal photograph","Assume humour means it has no historical use","Ignore captions and dates","Interpret symbols and message in relation to creator, audience and historical context"],"correct_index":3,"explanation":"Cartoons compress and exaggerate viewpoints. Context and visual details help explain the message and its limitations as evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An essay uses an event in 1965 as the cause of a policy adopted in 1960. What revision is needed?","options":["Keep the claim because all related events are interchangeable.","Remove every date from the essay.","Correct the chronology and identify earlier causes; the later event may be a consequence or later development.","Treat the later event as earlier without evidence."],"correct_index":2,"explanation":"A cause must precede its effect. Establish an accurate sequence and distinguish origins, consequences and later reinforcement before building a causal argument.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Mixed revision: Black Consciousness, transition and reconciliation; Source-based and essay examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b5bc364e-6c69-5a8f-bd8a-1a50c65192ef","title":"History · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"History","grade":"Grade 12","questions":[{"question":"What was a central emphasis of Black Consciousness associated with Steve Biko?","options":["Acceptance of apartheid's racial hierarchy","Withdrawal of all criticism of oppression","A claim that only legislation affects identity","Psychological liberation, dignity and self-reliance among oppressed black people"],"correct_index":3,"explanation":"Black Consciousness challenged internalised oppression and promoted agency and solidarity. Explain its context and influence using specific evidence.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why evaluate both achievements and limitations of reconciliation initiatives?","options":["Stated aims automatically prove success","Critical evaluation is incompatible with evidence","Their aims and actual effects may differ across people and issues","All testimony gives the same experience"],"correct_index":2,"explanation":"A balanced argument compares goals, processes and outcomes, including justice, acknowledgement and unresolved material inequalities.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why can globalisation affect African states differently?","options":["Every state has identical resources and institutions","Economic structures, bargaining power and domestic policies vary","Geography and history have no influence","All foreign investment has identical effects"],"correct_index":1,"explanation":"Different positions in trade, finance and production shape opportunities and constraints. Support comparisons with specific evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An editorial praises an international financial policy. What should a historian investigate?","options":["Only the font size","Whether praise proves neutrality","Who produced it, its interests, evidence and intended audience","Whether the headline rhymes"],"correct_index":2,"explanation":"Editorials provide perspectives and arguments. Assess evidence and context, and compare with other affected groups' experiences.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"An editorial welcomes a global financial policy while workers' accounts describe job losses. Which synthesis is strongest?","options":["Only the editorial counts because it is published.","Only negative effects can ever be historical evidence.","Evaluate the policy's different effects on groups using contextual evidence and each source's perspective.","Opposing accounts prove neither group experienced any effect."],"correct_index":2,"explanation":"Globalisation can distribute gains and adjustment costs unevenly. Assess specific claims, interests and context to form a qualified argument rather than presume one uniform outcome.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"Mixed revision: Black Consciousness, transition and reconciliation; Globalisation and a new world order","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=luMlDutfFbc%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"721e6a9a-f180-5ada-9572-dc2bd3ca1c43","title":"Tourism · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 12","questions":[{"question":"A hotel offers local jobs but pollutes the river. How should its sustainability be assessed?","options":["Jobs prove it is sustainable in every respect","Consider the economic benefit alongside environmental and social harms","Pollution is irrelevant to tourism","Only the hotel's advertising matters"],"correct_index":1,"explanation":"The three pillars must be considered together. Economic benefits do not cancel environmental damage without addressing it.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a tourism employee understand their employment contract?","options":["It sets out duties, terms and relevant employment conditions","It replaces every applicable labour law","It guarantees no workplace disagreement","It removes all responsibilities from both parties"],"correct_index":0,"explanation":"A contract helps clarify expectations. Its terms must be considered within the applicable legal framework and should be understood before agreement.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costs R1 500 before a 10% discount. Find the discounted price.","options":["R150","R1 650","R1 490","R1 350"],"correct_index":3,"explanation":"Discount = 1 500×0.10=R150. Subtract it to get R1 350. The discount amount is not the final price.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guide learns that an attraction is temporarily closed. What is the best response?","options":["Verify details, inform travellers and offer a suitable revised itinerary","Keep selling the unchanged itinerary without disclosure","Invent a reason that cannot be checked","Leave travellers stranded at the gate"],"correct_index":0,"explanation":"Good service uses accurate current information and practical alternatives. Explain material changes clearly before the visit where possible.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costing R1 500 offers 10% off, then charges a R200 booking fee. A competitor offers R1 450 all-inclusive for identical services. Which stated total is lower?","options":["The discounted tour's R1 350 because fees do not count.","Both cost R1 450.","The competitor's R1 450; the discounted tour totals R1 550.","The first tour costs R1 200 after adding the fee."],"correct_index":2,"explanation":"Discounted base price is 1 500×0.9=R1 350; adding R200 gives R1 550. Compare complete prices and equivalent services rather than the headline discount alone.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"Mixed revision: Responsible tourism, heritage and service; Integrated travel and destination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"e1203e24-1455-5960-983b-a29a1930ca8c","title":"Tourism · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 12","questions":[{"question":"Cape Town is UTC+2 and London is UTC+0 for this question. When it is 14:00 in Cape Town, what time is it in London?","options":["12:00","16:00","14:00","10:00"],"correct_index":0,"explanation":"Subtract the two-hour difference when moving from UTC+2 to UTC+0. Use the offsets provided; daylight-saving rules can differ by date.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tourist buys €200 at R21 per euro, ignoring fees. What is the rand cost?","options":["R9.52","R221","R3 800","R4 200"],"correct_index":3,"explanation":"Multiply foreign currency by rand per unit: 200×21=R4 200. Check the appropriate rate and fees for a real transaction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costs R1 500 before a 10% discount. Find the discounted price.","options":["R150","R1 650","R1 490","R1 350"],"correct_index":3,"explanation":"Discount = 1 500×0.10=R150. Subtract it to get R1 350. The discount amount is not the final price.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A guide learns that an attraction is temporarily closed. What is the best response?","options":["Verify details, inform travellers and offer a suitable revised itinerary","Keep selling the unchanged itinerary without disclosure","Invent a reason that cannot be checked","Leave travellers stranded at the gate"],"correct_index":0,"explanation":"Good service uses accurate current information and practical alternatives. Explain material changes clearly before the visit where possible.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tour costing R1 500 offers 10% off, then charges a R200 booking fee. A competitor offers R1 450 all-inclusive for identical services. Which stated total is lower?","options":["The discounted tour's R1 350 because fees do not count.","Both cost R1 450.","The competitor's R1 450; the discounted tour totals R1 550.","The first tour costs R1 200 after adding the fee."],"correct_index":2,"explanation":"Discounted base price is 1 500×0.9=R1 350; adding R200 gives R1 550. Compare complete prices and equivalent services rather than the headline discount alone.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadat