ondon?","options":["12:00","16:00","14:00","10:00"],"correct_index":0,"explanation":"Subtract the two-hour difference when moving from UTC+2 to UTC+0. Use the offsets provided; daylight-saving rules can differ by date.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tourist buys €200 at R21 per euro, ignoring fees. What is the rand cost?","options":["R9.52","R221","R3 800","R4 200"],"correct_index":3,"explanation":"Multiply foreign currency by rand per unit: 200×21=R4 200. Check the appropriate rate and fees for a real transaction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why consult communities when managing a heritage site?","options":["Heritage exists only for visitors","Community views can never change","Their knowledge, rights and interests are central to responsible management","Consultation guarantees agreement on every issue"],"correct_index":2,"explanation":"Participation improves legitimacy and interpretation. Manage differing interests transparently rather than assuming tourism overrides local needs.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which method provides structured customer feedback?","options":["Only counting advertising posters","Ignoring complaints","Assuming silence means perfect service","A clear post-visit survey with relevant questions"],"correct_index":3,"explanation":"A survey can collect comparable feedback. Include different guests, consider response bias and use findings to make improvements.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A hotel reports 95% satisfaction from a survey offered only to repeat guests. Which evaluation is sound?","options":["It proves 95% of every possible guest is satisfied.","Repeat guests always provide unbiased national tourism data.","The result describes respondents but may not represent first-time or dissatisfied guests.","Surveys cannot provide any useful service evidence."],"correct_index":2,"explanation":"The sampling method can exclude dissatisfied guests who never return. Include a broader guest sample and examine response rates before generalising the result.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Mixed revision: World time zones, icons and currency; Responsible tourism, heritage and service","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=vPhsHBIjpnI%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
